<div class="space-y-5"><x-textarea name="content" label="Nội dung câu hỏi" rows="4">{{ old('content', $question->content ?? '') }}</x-textarea><div class="grid gap-4 md:grid-cols-2"><x-select name="type" label="Loại câu hỏi"><option value="single" @selected(old('type',$question->type??'single')==='single')>Một đáp án</option><option value="multiple" @selected(old('type',$question->type??'single')==='multiple')>Nhiều đáp án</option></x-select><x-select name="difficulty" label="Độ khó">@foreach(['easy'=>'Dễ','medium'=>'Trung bình','hard'=>'Khó'] as $key=>$label)<option value="{{ $key }}" @selected(old('difficulty',$question->difficulty??'medium')===$key)>{{ $label }}</option>@endforeach</x-select></div><x-textarea name="explanation" label="Giải thích" rows="3">{{ old('explanation', $question->explanation ?? '') }}</x-textarea>
@php($rows=old('options',isset($question)?$question->options->map(fn($o)=>['content'=>$o->content,'is_correct'=>$o->is_correct])->all():[['content'=>'','is_correct'=>false],['content'=>'','is_correct'=>false]]))
<div><div class="mb-2 flex items-center justify-between"><h2 class="font-semibold">Các đáp án (2–6)</h2><x-button type="button" variant="secondary" id="add-option">Thêm đáp án</x-button></div><div id="options" class="space-y-2">@foreach($rows as $i=>$row)<div class="option-row flex items-center gap-3"><input type="checkbox" name="options[{{ $i }}][is_correct]" value="1" @checked(!empty($row['is_correct'])) class="rounded border-gray-300"><input name="options[{{ $i }}][content]" value="{{ $row['content'] }}" class="flex-1 rounded-md border-gray-300" placeholder="Nội dung đáp án"><button type="button" class="remove-option text-red-600">Xoá</button></div>@endforeach</div>@error('options')<p class="text-sm text-red-600">{{ $message }}</p>@enderror @error('correct_options')<p class="text-sm text-red-600">{{ $message }}</p>@enderror</div><x-button>{{ $submitLabel }}</x-button></div>
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const box=document.getElementById('options');const renumber=()=>[...box.querySelectorAll('.option-row')].forEach((row,i)=>row.querySelectorAll('[name]').forEach(el=>el.name=el.name.replace(/options\[\d+\]/,`options[${i}]`)));document.getElementById('add-option').addEventListener('click',()=>{if(box.children.length>=6)return;const i=box.children.length;box.insertAdjacentHTML('beforeend',`<div class="option-row flex items-center gap-3"><input type="checkbox" name="options[${i}][is_correct]" value="1" class="rounded border-gray-300"><input name="options[${i}][content]" class="flex-1 rounded-md border-gray-300" placeholder="Nội dung đáp án"><button type="button" class="remove-option text-red-600">Xoá</button></div>`)});box.addEventListener('click',e=>{if(e.target.classList.contains('remove-option')&&box.children.length>2){e.target.closest('.option-row').remove();renumber()}})});</script>@endpush
